style.css:
/* Basic Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    background-color: white; /* White background */
    color: black; /* Black text */
    font-family: Arial, sans-serif; /* Font family */
}

/* Header Styling */
header {
    background-color: black; /* Black header */
    color: white; /* White text in header */
    padding: 20px;
    text-align: center;
}

/* Link Styling */
a {
    color: black; /* Black links */
    text-decoration: none; /* Remove underline */
}

a:hover {
    text-decoration: underline; /* Underline on hover */
}

/* Button Styling */
button {
    background-color: black; /* Black button */
    color: white; /* White text on button */
    border: none;
    padding: 10px 20px;
    cursor: pointer;
}

button:hover {
    background-color: gray; /* Gray on hover */
}

/* Footer Styling */
footer {
    background-color: black; /* Black footer */
    color: white; /* White text in footer */
    text-align: center;
    padding: 10px;
}

/* Main Content Styling */
main {
    padding: 20px;
}

/* Other Elements */
h1, h2, h3, h4, h5, h6 {
    color: black; /* Black headings */
}

p {
    color: black; /* Black paragraphs */
    line-height: 1.6; /* Improved readability */
}
